<script setup lang="ts">
// A diagram from public/diagrams/<name>-light.svg and -dark.svg, the one matching the colour scheme.
// Slovak pages use the <name>-sk-*.svg variants with Slovak labels (generated by scripts/illustrations.py).
import { computed } from 'vue'
import { withBase } from 'vitepress'
import { useStrings } from './i18n'

const props = defineProps<{ name: string, alt: string, width?: number, height?: number }>()
const t = useStrings()
const file = (variant: string) => withBase(`/diagrams/${props.name}${t.value.svgSuffix}-${variant}.svg`)
const light = computed(() => file('light'))
const dark = computed(() => file('dark'))
</script>

<template>
  <figure class="ot-diagram">
    <a :href="light" target="_blank" rel="noopener" :aria-label="`${alt} ${t.fullSize}`">
      <img class="light-only" :src="light" :alt="alt" :width="width" :height="height" loading="lazy" decoding="async">
      <img class="dark-only" :src="dark" :alt="alt" :width="width" :height="height" loading="lazy" decoding="async">
    </a>
  </figure>
</template>
